window.LC_CHUNKS=window.LC_CHUNKS||{};window.LC_CHUNKS["university_physics_de"]=window.LC_CHUNKS["university_physics_de"]||{};window.LC_CHUNKS["university_physics_de"][33]={"university_physics_de:M33-L1":"<article class=\"lesson-standard\"><h1 id=\"L1\">M33-L1 – Atomare Feinstruktur und Drehimpulskopplung<\/h1>\n<p><strong>Kursbereich:<\/strong> M33 – Master: Atom-, Molekül- und optische Physik<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M12: Quantenzahlen und Drehimpulse;\nM23: atomare Spektroskopie; M32-L4: Linienprofile.<\/p>\n<p><strong>Lernziel:<\/strong> Die Eigenwerte von L·S für ein p-Elektron\nmit Spin 1/2 berechnen und ihre Modellgrenzen verstehen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Wie entstehen mehrere Spektrallinien aus zunächst gleich\nerscheinenden atomaren Energieniveaus? In Atomen koppeln die\nBahndrehimpulse der Elektronen an deren Spin. Für ein einfaches\nEin-Elektron-Modell beschreiben die Quantenzahlen l, s und j den\nGesamtdrehimpuls J=L+S. Die Kopplung führt zu unterschiedlichen Energien\nvon Zuständen mit verschiedenem j, selbst wenn n und l gleich\nbleiben.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Ein effektiver Spin-Bahn-Hamiltonoperator lautet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>H<\/mi><mrow><mi mathvariant=\"normal\">s<\/mi><mi mathvariant=\"normal\">o<\/mi><\/mrow><\/msub><mo>=<\/mo><mi>λ<\/mi><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"bold-italic\">𝑳<\/mi><mo>⋅<\/mo><mi mathvariant=\"bold-italic\">𝑺<\/mi><mi>/<\/mi><msup><mi>ℏ<\/mi><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">H_{\\mathrm{so}}=\\lambda\\,\\mathbf L\\cdot\\mathbf S/\\hbar^2<\/annotation><\/semantics><\/math>.\nWegen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi mathvariant=\"bold-italic\">𝑱<\/mi><mn>2<\/mn><\/msup><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"bold-italic\">𝑳<\/mi><mo>+<\/mo><mi mathvariant=\"bold-italic\">𝑺<\/mi><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\mathbf J^2=(\\mathbf L+\\mathbf S)^2<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"bold-italic\">𝑳<\/mi><mo>⋅<\/mo><mi mathvariant=\"bold-italic\">𝑺<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msup><mi mathvariant=\"bold-italic\">𝑱<\/mi><mn>2<\/mn><\/msup><mo>−<\/mo><msup><mi mathvariant=\"bold-italic\">𝑳<\/mi><mn>2<\/mn><\/msup><mo>−<\/mo><msup><mi mathvariant=\"bold-italic\">𝑺<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\mathbf L\\cdot\\mathbf S=[\\mathbf J^2-\\mathbf L^2-\\mathbf S^2]/2<\/annotation><\/semantics><\/math>.\nIm Zustand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>l<\/mi><mo>,<\/mo><mi>s<\/mi><mo>,<\/mo><mi>j<\/mi><mo>,<\/mo><msub><mi>m<\/mi><mi>j<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|l,s,j,m_j\\rangle<\/annotation><\/semantics><\/math>\nergibt das den dimensionslosen Eigenwert\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>j<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>j<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>l<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>l<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>s<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>s<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">[j(j+1)-l(l+1)-s(s+1)]/2<\/annotation><\/semantics><\/math>.\nDas Vorzeichen und die Größe von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>λ<\/mi><annotation encoding=\"application/x-tex\">\\lambda<\/annotation><\/semantics><\/math>\nhängen vom konkreten Atom und Niveau ab; hier ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>λ<\/mi><annotation encoding=\"application/x-tex\">\\lambda<\/annotation><\/semantics><\/math>\nein definierter effektiver Energieparameter.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>E<\/mi><mi>j<\/mi><\/msub><mo>=<\/mo><mfrac><mi>λ<\/mi><mn>2<\/mn><\/mfrac><mrow><mo stretchy=\"true\" form=\"prefix\">[<\/mo><mi>j<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>j<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>l<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>l<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mi>s<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>s<\/mi><mo>+<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"true\" form=\"postfix\">]<\/mo><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta E_j=\\frac{\\lambda}{2}\\left[j(j+1)-l(l+1)-s(s+1)\\right].<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für ein p-Elektron ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>l<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">l=1<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s=1/2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>j<\/mi><mo>∈<\/mo><mo stretchy=\"false\" form=\"prefix\">{<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>,<\/mo><mn>3<\/mn><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">}<\/mo><\/mrow><annotation encoding=\"application/x-tex\">j\\in\\{1/2,3/2\\}<\/annotation><\/semantics><\/math>.\nMit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=2\\,\\mathrm{meV}<\/annotation><\/semantics><\/math>\ngilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>E<\/mi><mrow><mn>3<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><mo>=<\/mo><mi>+<\/mi><mn>1<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Delta E_{3/2}=+1\\,\\mathrm{meV}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>E<\/mi><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><mo>=<\/mo><mi>−<\/mi><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Delta E_{1/2}=-2\\,\\mathrm{meV}<\/annotation><\/semantics><\/math>;\ndie modellierte Aufspaltung beträgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>3<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">3\\,\\mathrm{meV}<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt die zwei verschobenen Niveaus. Sie ist keine\nmaßstabsgetreue Darstellung eines bestimmten Elements.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_272_DE.svg\"\nalt=\"Energieniveaus eines p-Elektrons vor und nach vereinfachter Spin-Bahn-Kopplung; j gleich ein Halb und drei Halbe.\" />\n<figcaption aria-hidden=\"true\">Energieniveaus eines p-Elektrons vor und\nnach vereinfachter Spin-Bahn-Kopplung; j gleich ein Halb und drei\nHalbe.<\/figcaption>\n<\/figure>\n<p><em>Effektive Spin-Bahn-Aufspaltung für l = 1 und s = 1/2 bei\npositivem λ.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Welche Werte von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>j<\/mi><annotation encoding=\"application/x-tex\">j<\/annotation><\/semantics><\/math>\nsind für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>l<\/mi><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">l=2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s=1/2<\/annotation><\/semantics><\/math>\nerlaubt?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>E<\/mi><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\Delta E_{1/2}<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>l<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">l=1<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>s<\/mi><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">s=1/2<\/annotation><\/semantics><\/math>,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>λ<\/mi><mo>=<\/mo><mn>4<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\lambda=4\\,\\mathrm{meV}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum darf die schematische Aufspaltung nicht ungeprüft auf komplexe\nMehrelektronenatome übertragen werden?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>j<\/mi><mo>=<\/mo><mn>3<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">j=3/2<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>5<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">5/2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>E<\/mi><mrow><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><\/msub><mo>=<\/mo><mi>−<\/mi><mi>λ<\/mi><mo>=<\/mo><mi>−<\/mi><mn>4<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">m<\/mi><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Delta E_{1/2}=-\\lambda=-4\\,\\mathrm{meV}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Dort wirken zusätzlich Elektron-Elektron-Korrelationen, weitere\nKopplungsschemata und feldabhängige Effekte.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Der konstante Parameter λ fasst hier einen energieabhängigen\nmikroskopischen Operator zusammen. Hyperfeinstruktur,\nZeeman-Aufspaltung, relativistische Korrekturen jenseits dieser Näherung\nund Auswahlregeln für Übergangsintensitäten fehlen. Die NIST-Quelle\nbegründet Quantenzahlen und Kopplungsbezeichnungen, nicht den frei\ngewählten Zahlenwert.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Die energetische Struktur der Atomzustände bestimmt, auf welche\noptischen Frequenzen ein Übergang anspricht. <a\nhref=\"index.html?course=university_physics&amp;module=M33&amp;lesson=L2&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://physics.nist.gov/Pubs/AtSpec/node03.html\">NIST – Atomic Spectroscopy: Atomic States, Shells and Configurations<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Quantenzahlen, Drehimpulskopplung und Spin-Bahn-Feinstruktur; ausgewählte NIST-Definitionen; Fachlicher Bezug zur Lektion: M33-L1 – Atomare Feinstruktur und Drehimpulskopplung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-421-atomic-and-optical-physics-i-spring-2014/pages/readings/\">MIT OpenCourseWare – Atomic and Optical Physics I: Readings<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Literaturübersicht zur Atomphysik; kein Nachweis einzelner Rechenformeln; Fachlicher Bezug zur Lektion: M33-L1 – Atomare Feinstruktur und Drehimpulskopplung · Zuletzt abgerufen: 2026-11-20<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M33-L2":"<article class=\"lesson-standard\"><h1 id=\"L2\">M33-L2 – Zwei-Niveau-Atome und kohärente Rabi-Oszillationen<\/h1>\n<p><strong>Kursbereich:<\/strong> M33 – Master: Atom-, Molekül- und optische Physik<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M12: Zeitentwicklung in der\nQuantenmechanik; M26: Dichtematrix; M33-L1.<\/p>\n<p><strong>Lernziel:<\/strong> Eine resonante π-Pulsdauer aus der\nRabi-Frequenz bestimmen und die Bedeutung von Dekohärenz abgrenzen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein Atom, das durch ein schmales Lichtfeld zwischen zwei ausgewählten\nZuständen angeregt wird, bildet oft ein näherungsweises\nZwei-Niveau-System. Unter kohärenter resonanter Anregung kann die\nBesetzungswahrscheinlichkeit periodisch zwischen Grund- und angeregtem\nZustand wechseln. Für gemessene Fluoreszenz ist jedoch zusätzlich der\nZerfall des angeregten Zustands entscheidend.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Im rotierenden Bezugssystem und unter der Rotating-Wave-Näherung\nlässt sich der kohärente Antrieb als\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>H<\/mi><mi>/<\/mi><mi>ℏ<\/mi><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><msub><mi>σ<\/mi><mi>z<\/mi><\/msub><mo>+<\/mo><mi mathvariant=\"normal\">Ω<\/mi><msub><mi>σ<\/mi><mi>x<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">H/\\hbar=(\\Delta\\sigma_z+\\Omega\\sigma_x)/2<\/annotation><\/semantics><\/math>\nschreiben. Hier sind\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"normal\">Δ<\/mi><annotation encoding=\"application/x-tex\">\\Delta<\/annotation><\/semantics><\/math>\ndie Winkel-Frequenzverstimmung und\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"normal\">Ω<\/mi><annotation encoding=\"application/x-tex\">\\Omega<\/annotation><\/semantics><\/math>\ndie resonante Rabi-Winkelfrequenz. Startet das Atom im Grundzustand,\nergibt sich bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta=0<\/annotation><\/semantics><\/math>\nund ohne Dissipation\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mi>e<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Ω<\/mi><mi>t<\/mi><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">P_e(t)=\\sin^2(\\Omega t/2)<\/annotation><\/semantics><\/math>.\nEin sogenannter π-Puls erfüllt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Ω<\/mi><msub><mi>t<\/mi><mi>π<\/mi><\/msub><mo>=<\/mo><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Omega t_\\pi=\\pi<\/annotation><\/semantics><\/math>\nund kehrt die Besetzung idealisiert um. Zerfall und Dephasierung\nbenötigen optische Bloch-Gleichungen mit Relaxationstermen.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mi>e<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>t<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msup><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mspace width=\"-0.167em\"><\/mspace><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mfrac><mrow><mi mathvariant=\"normal\">Ω<\/mi><mi>t<\/mi><\/mrow><mn>2<\/mn><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>t<\/mi><mi>π<\/mi><\/msub><mo>=<\/mo><mfrac><mi>π<\/mi><mi mathvariant=\"normal\">Ω<\/mi><\/mfrac><mspace width=\"1.0em\"><\/mspace><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P_e(t)=\\sin^2\\!\\left(\\frac{\\Omega t}{2}\\right),\\qquad t_\\pi=\\frac{\\pi}{\\Omega}\\quad(\\Delta=0).<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Ω<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>π<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">z<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Omega/(2\\pi)=1{,}0\\,\\mathrm{MHz}<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mi>π<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>50<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">μ<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">t_\\pi=0{,}50\\,\\mathrm{\\mu s}<\/annotation><\/semantics><\/math>.\nNach\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>25<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">μ<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">0{,}25\\,\\mathrm{\\mu s}<\/annotation><\/semantics><\/math>\nliegt die ideale Besetzung bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P_e=1/2<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>P<\/mi><mi>e<\/mi><\/msub><annotation encoding=\"application/x-tex\">P_e<\/annotation><\/semantics><\/math>\nim Verlauf zweier Perioden. Die zugrunde liegende Frequenz ist eine\nWinkelfrequenz; der Faktor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2\\pi<\/annotation><\/semantics><\/math>\ndarf nicht übersehen werden.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_301_DE.svg\"\nalt=\"Sinusquadratisch schwankende Population des angeregten Zustands, markierter π-Puls und 2π-Puls.\" />\n<figcaption aria-hidden=\"true\">Sinusquadratisch schwankende Population\ndes angeregten Zustands, markierter π-Puls und 2π-Puls.<\/figcaption>\n<\/figure>\n<p><em>Resonante Rabi-Anregung ohne Dämpfung: ein π-Puls invertiert die\nBesetzung.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie lang ist der resonante π-Puls bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Ω<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>π<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>2<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">z<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Omega/(2\\pi)=2\\,\\mathrm{MHz}<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welche Besetzung erwartet man idealisiert bei einem\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2\\pi<\/annotation><\/semantics><\/math>-Puls?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Welche Prozesse dämpfen Rabi-Oszillationen?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>t<\/mi><mi>π<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>25<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">μ<\/mi><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">t_\\pi=0{,}25\\,\\mathrm{\\mu s}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P_e=0<\/annotation><\/semantics><\/math>,\nfalls anfangs der Grundzustand vorlag.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Spontane Emission, Stöße, Fluktuationen der Anregung und\nPhasenrauschen.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Sinusquadratformel verlangt resonante, kohärente Anregung,\nhinreichend kleine Gegenrotationsanteile und vernachlässigbaren Zerfall\nwährend des Pulses. Sie ist keine allgemeine Lösung für starke offene\nSysteme. MIT belegt den Themenrahmen optischer Bloch-Gleichungen; das\nZahlenbeispiel ist unabhängig konstruiert.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Nach dem isolierten Atom folgt die Energie- und Schwingungsstruktur\nvon Molekülen. <a href=\"index.html?course=university_physics&amp;module=M33&amp;lesson=L3&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste\nLektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-422-atomic-and-optical-physics-ii-spring-2013/pages/lecture-notes/\">MIT OpenCourseWare – Atomic and Optical Physics II: Lecture Notes<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kurs- und Skriptindex zu Quantenoptik, Bloch-Gleichungen, Kühlung und Metrologie; ausgewählte Themen; Fachlicher Bezug zur Lektion: M33-L2 – Zwei-Niveau-Atome und kohärente Rabi-Oszillationen · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-422-atomic-and-optical-physics-ii-spring-2013/pages/syllabus/\">MIT OpenCourseWare – Atomic and Optical Physics II: Syllabus<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Lehrplan zu offenen Quantensystemen, optischen Wechselwirkungen und ultrakalten Atomen; Fachlicher Bezug zur Lektion: M33-L2 – Zwei-Niveau-Atome und kohärente Rabi-Oszillationen · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M33-L3":"<article class=\"lesson-standard\"><h1 id=\"L3\">M33-L3 – Molekülpotentiale, Morse-Oszillator und Franck-Condon-Faktoren<\/h1>\n<p><strong>Kursbereich:<\/strong> M33 – Master: Atom-, Molekül- und optische Physik<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M12: Potentialtopf und harmonischer\nOszillator; M33-L1; Molekülbindungsgrundlagen.<\/p>\n<p><strong>Lernziel:<\/strong> Elektronenenergie und Kernabstoßung\nkorrekt zuordnen und die Anharmonizität eines Morse-Oszillators\nauswerten.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Bei Molekülen bewegen sich die schweren Kerne oft wesentlich\nlangsamer als die Elektronen. Die Born-Oppenheimer-Näherung löst deshalb\nfür feste Kernkoordinaten zunächst das Elektronenproblem. Wurde die\nKern-Kern-Abstoßung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>V<\/mi><mrow><mi>n<\/mi><mi>n<\/mi><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>R<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">V_{nn}(R)<\/annotation><\/semantics><\/math>\nnicht in den elektronischen Hamiltonoperator aufgenommen, ist die\nKernpotentialkurve\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>R<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>E<\/mi><mrow><mi>e<\/mi><mi>l<\/mi><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>R<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>+<\/mo><msub><mi>V<\/mi><mrow><mi>n<\/mi><mi>n<\/mi><\/mrow><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>R<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">U(R)=E_{el}(R)+V_{nn}(R)<\/annotation><\/semantics><\/math>;\nist sie bereits enthalten, darf sie nicht ein zweites Mal addiert\nwerden. Die Kerne bewegen sich auf dieser Potentialfläche, solange\nnichtadiabatische Kopplungen klein bleiben.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Ein gebundenes zweiatomiges Molekül kann näherungsweise durch ein\nMorse-Potential\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>U<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>R<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><msub><mi>D<\/mi><mi>e<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mn>1<\/mn><mo>−<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mi>a<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>R<\/mi><mo>−<\/mo><msub><mi>R<\/mi><mi>e<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">U(R)=D_e[1-e^{-a(R-R_e)}]^2<\/annotation><\/semantics><\/math>\nmit Minimum null beschrieben werden.\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>D<\/mi><mi>e<\/mi><\/msub><annotation encoding=\"application/x-tex\">D_e<\/annotation><\/semantics><\/math>\nist die Dissoziationsenergie vom Potentialminimum,\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>R<\/mi><mi>e<\/mi><\/msub><annotation encoding=\"application/x-tex\">R_e<\/annotation><\/semantics><\/math>\ndie Gleichgewichtsbindungslänge. Die Energieniveaus relativ zum Minimum\nsind\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mi>v<\/mi><\/msub><mo>=<\/mo><mi>ℏ<\/mi><msub><mi>ω<\/mi><mi>e<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>v<\/mi><mo>+<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>−<\/mo><mo stretchy=\"false\" form=\"prefix\">[<\/mo><mi>ℏ<\/mi><msub><mi>ω<\/mi><mi>e<\/mi><\/msub><msup><mo stretchy=\"false\" form=\"postfix\">]<\/mo><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>v<\/mi><mo>+<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>4<\/mn><msub><mi>D<\/mi><mi>e<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E_v=\\hbar\\omega_e(v+1/2)-[\\hbar\\omega_e]^2(v+1/2)^2/(4D_e)<\/annotation><\/semantics><\/math>,\nsolange gebundene Zustände vorliegen. Der Abstand benachbarter Niveaus\nnimmt mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>v<\/mi><annotation encoding=\"application/x-tex\">v<\/annotation><\/semantics><\/math>\nab. Bei vibronischen Übergängen beschreibt der Franck-Condon-Faktor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>q<\/mi><mrow><mi>v<\/mi><mi>′<\/mi><mi>v<\/mi><\/mrow><\/msub><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><msubsup><mi>χ<\/mi><mrow><mi>v<\/mi><mi>′<\/mi><\/mrow><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>e<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msubsup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><msubsup><mi>χ<\/mi><mi>v<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>g<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msubsup><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><msup><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">q_{v\\prime v}=|\\langle\\chi^{(e)}_{v\\prime}|\\chi^{(g)}_v\\rangle|^2<\/annotation><\/semantics><\/math>\nden reinen Schwingungsüberlapp; er ist ohne elektronisches\nDipolmatrixelement, Besetzungen und Auswahlregeln keine vollständige\nIntensität.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mi>v<\/mi><\/msub><mo>=<\/mo><mi>ℏ<\/mi><msub><mi>ω<\/mi><mi>e<\/mi><\/msub><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mi>v<\/mi><mo>+<\/mo><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mo>−<\/mo><mfrac><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>ℏ<\/mi><msub><mi>ω<\/mi><mi>e<\/mi><\/msub><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><\/mrow><mrow><mn>4<\/mn><msub><mi>D<\/mi><mi>e<\/mi><\/msub><\/mrow><\/mfrac><msup><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mi>v<\/mi><mo>+<\/mo><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mn>2<\/mn><\/msup><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">E_v=\\hbar\\omega_e\\left(v+\\frac12\\right)-\\frac{(\\hbar\\omega_e)^2}{4D_e}\\left(v+\\frac12\\right)^2.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Als konstruiertes Beispiel setzen wir\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ℏ<\/mi><msub><mi>ω<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>20<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\hbar\\omega_e=0{,}20\\,\\mathrm{eV}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">D_e=5\\,\\mathrm{eV}<\/annotation><\/semantics><\/math>.\nDer dimensionslose Anharmonizitätsfaktor ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><mi>ℏ<\/mi><msub><mi>ω<\/mi><mi>e<\/mi><\/msub><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>4<\/mn><msub><mi>D<\/mi><mi>e<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>01<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x_e=\\hbar\\omega_e/(4D_e)=0{,}01<\/annotation><\/semantics><\/math>.\nFür den Übergang\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>v<\/mi><mo>=<\/mo><mn>0<\/mn><mo>→<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">v=0\\rightarrow1<\/annotation><\/semantics><\/math>\nfolgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mn>1<\/mn><\/msub><mo>−<\/mo><msub><mi>E<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mi>ℏ<\/mi><msub><mi>ω<\/mi><mi>e<\/mi><\/msub><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mn>2<\/mn><msub><mi>x<\/mi><mi>e<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>196<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">E_1-E_0=\\hbar\\omega_e(1-2x_e)=0{,}196\\,\\mathrm{eV}<\/annotation><\/semantics><\/math>.\nIm harmonischen Modell wären es\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>200<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">0{,}200\\,\\mathrm{eV}<\/annotation><\/semantics><\/math>.\nDie Grafik stellt das Potential und einige enger werdende Niveaus\nschematisch dar.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_029_DE.svg\"\nalt=\"Morse-Potentialkurve eines Moleküls mit asymptotischer Dissoziationsgrenze und näherungsweisen gebundenen Schwingungsniveaus.\" />\n<figcaption aria-hidden=\"true\">Morse-Potentialkurve eines Moleküls mit\nasymptotischer Dissoziationsgrenze und näherungsweisen gebundenen\nSchwingungsniveaus.<\/figcaption>\n<\/figure>\n<p><em>Anharmonische Molekülschwingungen: der Niveauabstand nimmt mit\nder Anregung ab.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>x<\/mi><mi>e<\/mi><\/msub><annotation encoding=\"application/x-tex\">x_e<\/annotation><\/semantics><\/math>\nfür\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ℏ<\/mi><msub><mi>ω<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>10<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\hbar\\omega_e=0{,}10\\,\\mathrm{eV}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>D<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><mn>2<\/mn><mo>,<\/mo><mn>5<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">D_e=2{,}5\\,\\mathrm{eV}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie groß ist bei diesen Werten\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mn>1<\/mn><\/msub><mo>−<\/mo><msub><mi>E<\/mi><mn>0<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">E_1-E_0<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Unter welcher Voraussetzung wird\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>V<\/mi><mrow><mi>n<\/mi><mi>n<\/mi><\/mrow><\/msub><annotation encoding=\"application/x-tex\">V_{nn}<\/annotation><\/semantics><\/math>\nzusätzlich zu\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>E<\/mi><mrow><mi>e<\/mi><mi>l<\/mi><\/mrow><\/msub><annotation encoding=\"application/x-tex\">E_{el}<\/annotation><\/semantics><\/math>\naddiert?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>x<\/mi><mi>e<\/mi><\/msub><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>01<\/mn><\/mrow><annotation encoding=\"application/x-tex\">x_e=0{,}01<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>0<\/mn><mo>,<\/mo><mn>10<\/mn><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo>−<\/mo><mn>0<\/mn><mo>,<\/mo><mn>02<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>098<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">V<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">0{,}10(1-0{,}02)=0{,}098\\,\\mathrm{eV}<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Nur wenn\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>E<\/mi><mrow><mi>e<\/mi><mi>l<\/mi><\/mrow><\/msub><annotation encoding=\"application/x-tex\">E_{el}<\/annotation><\/semantics><\/math>\ndie Kern-Kern-Abstoßung noch nicht enthält.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Das Morse-Modell ist besonders für einzelne Bindungskoordinaten\nnützlich, beschreibt aber keine beliebigen Mehratomschwingungen oder\nelektronischen Flächenkreuzungen. Die exakte Morse-Niveauformel gilt nur\nbis zur endlichen Zahl gebundener Zustände. Der Franck-Condon-Ansatz\nsetzt für einfache Intensitätsaussagen zusätzlich eine näherungsweise\nortsunabhängige elektronische Übergangsmatrix (Condon-Näherung)\nvoraus.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Molekulare Spektroskopie verbindet Zustände mit optischen Übergängen.\nNun wird das Lichtfeld selbst quantisiert. <a\nhref=\"index.html?course=university_physics&amp;module=M33&amp;lesson=L4&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.physchem.no/physchem_book/chapters-17-born-oppenheimer.html\">Physical Chemistry II – The Born–Oppenheimer Approximation<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Festkern-Näherung, Kernabstoßung als Potentialbeitrag und Morse-Niveaus; Fachlicher Bezug zur Lektion: M33-L3 – Molekülpotentiale, Morse-Oszillator und Franck-Condon-Faktoren · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://www.pci.tu-bs.de/aggericke/PC4e_osv/Spectroscopy050119/node23.html\">TU Braunschweig – Franck–Condon Principle<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Franck–Condon-Faktoren als Schwingungsüberlappung; kein vollständiger Intensitätsnachweis; Fachlicher Bezug zur Lektion: M33-L3 – Molekülpotentiale, Morse-Oszillator und Franck-Condon-Faktoren · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M33-L4":"<article class=\"lesson-standard\"><h1 id=\"L4\">M33-L4 – Photonenstatistik: Fock-Zustände, kohärentes Licht und Korrelationen<\/h1>\n<p><strong>Kursbereich:<\/strong> M33 – Master: Atom-, Molekül- und optische Physik<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M13:\nWahrscheinlichkeitsverteilungen; M26: Dichteoperator; M33-L2.<\/p>\n<p><strong>Lernziel:<\/strong> Poisson-Photonenzahlen berechnen und\ng(2)(0) für Fock- und kohärente Zustände unterscheiden.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Ein einzelner quantisierter Lichtmodus besitzt diskrete\nPhotonenzahlzustände |n⟩. Ein kohärenter Zustand |α⟩ ist eine\nÜberlagerung vieler Photonenzahlen mit Poisson-Verteilung und mittlerer\nZahl n̄=|α|². Bereits die Statistik der Intensitätsschwankungen kann\nzwischen kohärentem Licht, idealem Ein-Photon-Licht und thermischem\nLicht unterscheiden.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für einen kohärenten Zustand ist die Wahrscheinlichkeit von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>n<\/mi><annotation encoding=\"application/x-tex\">n<\/annotation><\/semantics><\/math>\nPhotonen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mover><mi>n<\/mi><mo accent=\"true\">‾<\/mo><\/mover><\/mrow><\/msup><msup><mover><mi>n<\/mi><mo accent=\"true\">‾<\/mo><\/mover><mi>n<\/mi><\/msup><mi>/<\/mi><mi>n<\/mi><mi>!<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P_n=e^{-\\bar n}\\bar n^n/n!<\/annotation><\/semantics><\/math>.\nDamit sind Mittelwert und Varianz gleich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mover><mi>n<\/mi><mo accent=\"true\">‾<\/mo><\/mover><annotation encoding=\"application/x-tex\">\\bar n<\/annotation><\/semantics><\/math>.\nDie normierte Zweitordnungskorrelation für einen einzelnen Modus lautet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>g<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mover><mi>n<\/mi><mo accent=\"true\">̂<\/mo><\/mover><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mover><mi>n<\/mi><mo accent=\"true\">̂<\/mo><\/mover><mo>−<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mover><mi>n<\/mi><mo accent=\"true\">̂<\/mo><\/mover><msup><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">g^{(2)}(0)=\\langle\\hat n(\\hat n-1)\\rangle/\\langle\\hat n\\rangle^2<\/annotation><\/semantics><\/math>.\nSie ist für ideale kohärente Zustände gleich eins; für einen\nFock-Zustand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mi>N<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|N\\rangle<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>N<\/mi><mo>&gt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">N&gt;0<\/annotation><\/semantics><\/math>\nist sie\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>−<\/mo><mn>1<\/mn><mi>/<\/mi><mi>N<\/mi><\/mrow><annotation encoding=\"application/x-tex\">1-1/N<\/annotation><\/semantics><\/math>,\nalso für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|1\\rangle<\/annotation><\/semantics><\/math>\nnull. Die Normierung ist für den Vakuumzustand mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mi>n<\/mi><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\langle n\\rangle=0<\/annotation><\/semantics><\/math>\nnicht definiert.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mi>n<\/mi><\/msub><mo>=<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mover><mi>n<\/mi><mo accent=\"true\">‾<\/mo><\/mover><\/mrow><\/msup><mfrac><msup><mover><mi>n<\/mi><mo accent=\"true\">‾<\/mo><\/mover><mi>n<\/mi><\/msup><mrow><mi>n<\/mi><mi>!<\/mi><\/mrow><\/mfrac><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msup><mi>g<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mfrac><mrow><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mover><mi>n<\/mi><mo accent=\"true\">̂<\/mo><\/mover><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mover><mi>n<\/mi><mo accent=\"true\">̂<\/mo><\/mover><mo>−<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><mrow><mo stretchy=\"false\" form=\"prefix\">⟨<\/mo><mover><mi>n<\/mi><mo accent=\"true\">̂<\/mo><\/mover><msup><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><mn>2<\/mn><\/msup><\/mrow><\/mfrac><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">P_n=e^{-\\bar n}\\frac{\\bar n^n}{n!},\\qquad g^{(2)}(0)=\\frac{\\langle\\hat n(\\hat n-1)\\rangle}{\\langle\\hat n\\rangle^2}.<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover><mi>n<\/mi><mo accent=\"true\">‾<\/mo><\/mover><mo>=<\/mo><mn>4<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\bar n=4<\/annotation><\/semantics><\/math>\nergibt sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>4<\/mn><\/mrow><\/msup><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0183<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P_0=e^{-4}\\approx0{,}0183<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>P<\/mi><mn>1<\/mn><\/msub><mo>=<\/mo><mn>4<\/mn><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>4<\/mn><\/mrow><\/msup><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>0733<\/mn><\/mrow><annotation encoding=\"application/x-tex\">P_1=4e^{-4}\\approx0{,}0733<\/annotation><\/semantics><\/math>.\nDie Standardabweichung der Photonenzahl ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msqrt><mn>4<\/mn><\/msqrt><mo>=<\/mo><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\sqrt4=2<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt die Poisson-Balken und als Vergleich die ideale\nEinzelphotonen-Besetzung, die immer bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>n<\/mi><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">n=1<\/annotation><\/semantics><\/math>\nliegt. Sie zeigt Zustandsstatistik, nicht Detektoreffizienz.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_043_DE.svg\"\nalt=\"Balkendiagramm der Poisson-Photonenzahlverteilung mit Mittelwert vier, daneben ideale Einzelphotonen-Verteilung.\" />\n<figcaption aria-hidden=\"true\">Balkendiagramm der\nPoisson-Photonenzahlverteilung mit Mittelwert vier, daneben ideale\nEinzelphotonen-Verteilung.<\/figcaption>\n<\/figure>\n<p><em>Kohärentes Licht besitzt Poisson-Photonenzahlen; ein idealer\nEin-Photon-Zustand hat feste Photonenzahl.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Berechne\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>P<\/mi><mn>0<\/mn><\/msub><annotation encoding=\"application/x-tex\">P_0<\/annotation><\/semantics><\/math>\nbei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mover><mi>n<\/mi><mo accent=\"true\">‾<\/mo><\/mover><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\bar n=1<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie groß ist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>g<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">g^{(2)}(0)<\/annotation><\/semantics><\/math>\neines idealen Fock-Zustands\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">|<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">⟩<\/mo><\/mrow><annotation encoding=\"application/x-tex\">|2\\rangle<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum bedeutet\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>g<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><\/mrow><annotation encoding=\"application/x-tex\">g^{(2)}(0)=1<\/annotation><\/semantics><\/math>\nnicht automatisch ein perfektes Laserexperiment?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mi>e<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>368<\/mn><\/mrow><annotation encoding=\"application/x-tex\">e^{-1}\\approx0{,}368<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>1<\/mn><mo>−<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo>=<\/mo><mn>0<\/mn><mo>,<\/mo><mn>5<\/mn><\/mrow><annotation encoding=\"application/x-tex\">1-1/2=0{,}5<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Reale Messungen hängen von Moden, Hintergrund, Zeitauflösung und\nVerlusten ab; der Wert allein spezifiziert nicht das ganze Feld.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Zahlen gelten für einen idealen einzelnen optischen Modus und\ngenau definierte Zustände. Mehrmodigkeit, Verluste, Detektorrauschen und\ndas zeitliche Messfenster ändern gemessene Korrelationen. Der\nCornell-Verweis ist ein Lehrveranstaltungsindex; die Statistikformeln\nwerden durch den ergänzenden Fachtext gestützt.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Photonen übertragen bei Absorption und Emission auch Impuls. Das\nerlaubt die Kühlung langsamer Atome. <a\nhref=\"index.html?course=university_physics&amp;module=M33&amp;lesson=L5&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://mochizuki-tus.github.io/QM_Textbook_EN/ch60_photons_phonons.html\">Quantum Mechanics – Field Quantization and Photon Statistics<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Poisson-Verteilung kohärenter Zustände und g(2)(0) für Fock-Zustände; Fachlicher Bezug zur Lektion: M33-L4 – Photonenstatistik: Fock-Zustände, kohärentes Licht und Korrelationen · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://courses.cit.cornell.edu/ece531/Lectures/Lectures.htm\">Cornell – ECE Quantum Optics Lecture Index<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Vorlesungsindex zu Photonenstatistik und quantenoptischer Kohärenz; allgemeine Orientierung; Fachlicher Bezug zur Lektion: M33-L4 – Photonenstatistik: Fock-Zustände, kohärentes Licht und Korrelationen · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M33-L5":"<article class=\"lesson-standard\"><h1 id=\"L5\">M33-L5 – Laserkühlung: Doppler-Kraft und Temperaturgrenze<\/h1>\n<p><strong>Kursbereich:<\/strong> M33 – Master: Atom-, Molekül- und optische Physik<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M1: Impuls und Energie; M33-L2:\nZwei-Niveau-System; M33-L4: Photonen.<\/p>\n<p><strong>Lernziel:<\/strong> Die Doppler-Grenztemperatur aus der\nnatürlichen Linienbreite unter klar benannten Modellannahmen\nberechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Bei der Doppler-Kühlung werden Atome mit rotverstimmtem Licht\nbestrahlt, sodass ein Atom bevorzugt Photonen des gegen seine Bewegung\ngerichteten Strahls absorbiert. Der über viele Streuereignisse\ngemittelte Impulsübertrag bremst langsame Atome. Spontane Emission\nverursacht gleichzeitig zufällige Rückstöße und damit Impulsdiffusion.\nDas Gleichgewicht aus Dämpfung und Diffusion setzt dem einfachen Modell\neine Temperaturgrenze.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für eine geschlossene Zwei-Niveau-Übergangslinie mit spontaner\nZerfallsrate\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"normal\">Γ<\/mi><annotation encoding=\"application/x-tex\">\\Gamma<\/annotation><\/semantics><\/math>\n(in\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi mathvariant=\"normal\">s<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><annotation encoding=\"application/x-tex\">\\mathrm{s}^{-1}<\/annotation><\/semantics><\/math>\nals Winkel-Frequenzbreite), schwache Sättigung und optimale\nRotverstimmung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><mi>−<\/mi><mi mathvariant=\"normal\">Γ<\/mi><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta=-\\Gamma/2<\/annotation><\/semantics><\/math>\nergibt das elementare Doppler-Modell\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>T<\/mi><mi>D<\/mi><\/msub><mo>=<\/mo><mi>ℏ<\/mi><mi mathvariant=\"normal\">Γ<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><msub><mi>k<\/mi><mi>B<\/mi><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">T_D=\\hbar\\Gamma/(2k_B)<\/annotation><\/semantics><\/math>.\nDer Faktor\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"normal\">Γ<\/mi><annotation encoding=\"application/x-tex\">\\Gamma<\/annotation><\/semantics><\/math>\nist die Linienbreite im Winkel-Frequenzmaß; wenn die Breite als\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Γ<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>π<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\Gamma/(2\\pi)<\/annotation><\/semantics><\/math>\nin Hertz genannt wird, muss sie vor der Rechnung mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mn>2<\/mn><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">2\\pi<\/annotation><\/semantics><\/math>\nmultipliziert werden. Diese Temperatur ist keine absolute Grenze aller\nKühlverfahren.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>T<\/mi><mi>D<\/mi><\/msub><mo>=<\/mo><mfrac><mrow><mi>ℏ<\/mi><mi mathvariant=\"normal\">Γ<\/mi><\/mrow><mrow><mn>2<\/mn><msub><mi>k<\/mi><mi>B<\/mi><\/msub><\/mrow><\/mfrac><mspace width=\"2.0em\"><\/mspace><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mo>=<\/mo><mi>−<\/mi><mfrac><mi mathvariant=\"normal\">Γ<\/mi><mn>2<\/mn><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">T_D=\\frac{\\hbar\\Gamma}{2k_B}\\qquad\\left(\\Delta=-\\frac{\\Gamma}{2}\\right).<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Für einen modellierten Übergang mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Γ<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>π<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>6<\/mn><mo>,<\/mo><mn>0<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">M<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">z<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Gamma/(2\\pi)=6{,}0\\,\\mathrm{MHz}<\/annotation><\/semantics><\/math>\nist\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Γ<\/mi><mo>=<\/mo><mn>2<\/mn><mi>π<\/mi><mo>⋅<\/mo><mn>6<\/mn><mo>,<\/mo><mn>0<\/mn><mo>⋅<\/mo><msup><mn>10<\/mn><mn>6<\/mn><\/msup><mspace width=\"0.167em\"><\/mspace><msup><mi mathvariant=\"normal\">s<\/mi><mrow><mi>−<\/mi><mn>1<\/mn><\/mrow><\/msup><\/mrow><annotation encoding=\"application/x-tex\">\\Gamma=2\\pi\\cdot6{,}0\\cdot10^6\\,\\mathrm{s}^{-1}<\/annotation><\/semantics><\/math>.\nMit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ℏ<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>054571817<\/mn><mo>⋅<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>34<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">J<\/mi><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">s<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\hbar=1{,}054571817\\cdot10^{-34}\\,\\mathrm{J\\,s}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>k<\/mi><mi>B<\/mi><\/msub><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>380649<\/mn><mo>⋅<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>23<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">J<\/mi><mi mathvariant=\"normal\">/<\/mi><mi mathvariant=\"normal\">K<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">k_B=1{,}380649\\cdot10^{-23}\\,\\mathrm{J/K}<\/annotation><\/semantics><\/math>\nergibt sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>T<\/mi><mi>D<\/mi><\/msub><mo>≈<\/mo><mn>1<\/mn><mo>,<\/mo><mn>44<\/mn><mo>⋅<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>4<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><mi mathvariant=\"normal\">K<\/mi><mo>=<\/mo><mn>144<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">μ<\/mi><mi mathvariant=\"normal\">K<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">T_D\\approx1{,}44\\cdot10^{-4}\\,\\mathrm K=144\\,\\mathrm{\\mu K}<\/annotation><\/semantics><\/math>.\nDie Grafik illustriert die gegenläufigen Strahlen und die\nReibungskraft.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_145_DE.svg\"\nalt=\"Zwei gegenläufige rotverstimmte Laserstrahlen auf ein bewegtes Atom, rücktreibender Impuls und schematische Bremskraft.\" />\n<figcaption aria-hidden=\"true\">Zwei gegenläufige rotverstimmte\nLaserstrahlen auf ein bewegtes Atom, rücktreibender Impuls und\nschematische Bremskraft.<\/figcaption>\n<\/figure>\n<p><em>Doppler-Kühlung beruht auf bewegungsabhängiger Absorption und\nkonkurrierender Rückstoßdiffusion.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie ändert sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>T<\/mi><mi>D<\/mi><\/msub><annotation encoding=\"application/x-tex\">T_D<\/annotation><\/semantics><\/math>,\nwenn\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi mathvariant=\"normal\">Γ<\/mi><annotation encoding=\"application/x-tex\">\\Gamma<\/annotation><\/semantics><\/math>\nverdoppelt wird?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welche Vorzeichenbedingung besitzt die Verstimmung der\nKühlstrahlen?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum sind tiefere Temperaturen als\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>T<\/mi><mi>D<\/mi><\/msub><annotation encoding=\"application/x-tex\">T_D<\/annotation><\/semantics><\/math>\nphysikalisch möglich?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Sie verdoppelt sich im selben Modell.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mo>&lt;<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta&lt;0<\/annotation><\/semantics><\/math>\n(rotverstimmt).<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Zusätzliche interne Atomstruktur und Polarisationsgradienten\nerlauben andere Kühlmechanismen; zudem können weitere Verfahren\nanschließen.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die Formel setzt niedrige Intensität, ein praktisch geschlossenes\nZwei-Niveau-Übergangssystem und geeignete Gegenstrahlen voraus.\nMehrniveauatome, Sub-Doppler-Kühlung, endliche Rückstoßenergie und\nmagneto-optische Fallen verlangen differenziertere Modelle. Die\nBeispielbreite ist keine gemessene Speziesangabe.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Gekühlte Atome lassen sich in räumlichen Fallen speichern und\nkontrolliert untersuchen. <a\nhref=\"index.html?course=university_physics&amp;module=M33&amp;lesson=L6&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-422-atomic-and-optical-physics-ii-spring-2013/\">MIT OpenCourseWare – Atomic and Optical Physics II<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Themen Laserkräfte, Kühlung und ultrakalte Atome; kein Beweis aller Doppler-Modellgrenzen; Fachlicher Bezug zur Lektion: M33-L5 – Laserkühlung: Doppler-Kraft und Temperaturgrenze · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://opg.optica.org/abstract.cfm?uri=iqec-1988-PD1\">Optica – Observation of Atoms Laser-Cooled Below the Doppler Limit<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Doppler-Grenztemperatur im einfachen Zwei-Niveau-Modell und Hinweis auf Sub-Doppler-Verfahren; Fachlicher Bezug zur Lektion: M33-L5 – Laserkühlung: Doppler-Kraft und Temperaturgrenze · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M33-L6":"<article class=\"lesson-standard\"><h1 id=\"L6\">M33-L6 – Atomfallen und quantisierte Bewegung im harmonischen Potential<\/h1>\n<p><strong>Kursbereich:<\/strong> M33 – Master: Atom-, Molekül- und optische Physik<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M12: harmonischer Oszillator;\nM33-L5: Kühlung; M31: Modellgrenzen.<\/p>\n<p><strong>Lernziel:<\/strong> Für eine harmonische Atomfalle Energien\nund räumliche Grundzustandsbreite berechnen.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>Optische Dipolfallen, magnetische Fallen und Ionenfallen können\nTeilchen in einem räumlichen Potential festhalten. In der Nähe eines\nstabilen Minimums ist eine Taylorentwicklung bis zur zweiten Ordnung\nhäufig sinnvoll. In einer Raumrichtung resultiert ein harmonischer\nOszillator. Seine quantisierte Bewegung unterscheidet sich vom\nklassischen Bild eines völlig ruhenden Atoms, weil selbst der\nGrundzustand eine endliche räumliche Ausdehnung besitzt.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>V<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>≃<\/mo><msub><mi>V<\/mi><mn>0<\/mn><\/msub><mo>+<\/mo><mstyle displaystyle=\"false\"><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><\/mstyle><mi>m<\/mi><msup><mi>ω<\/mi><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo>−<\/mo><msub><mi>x<\/mi><mn>0<\/mn><\/msub><msup><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mn>2<\/mn><\/msup><\/mrow><annotation encoding=\"application/x-tex\">V(x)\\simeq V_0+\\tfrac12m\\omega^2(x-x_0)^2<\/annotation><\/semantics><\/math>\nfolgen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mi>n<\/mi><\/msub><mo>−<\/mo><msub><mi>V<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mi>ℏ<\/mi><mi>ω<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>n<\/mi><mo>+<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">E_n-V_0=\\hbar\\omega(n+1/2)<\/annotation><\/semantics><\/math>\nund die Standardabweichung des Ortes im Grundzustand\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>σ<\/mi><mi>x<\/mi><\/msub><mo>=<\/mo><msqrt><mrow><mi>ℏ<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>m<\/mi><mi>ω<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msqrt><\/mrow><annotation encoding=\"application/x-tex\">\\sigma_x=\\sqrt{\\hbar/(2m\\omega)}<\/annotation><\/semantics><\/math>.\nDer Schwerpunkt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>x<\/mi><mn>0<\/mn><\/msub><annotation encoding=\"application/x-tex\">x_0<\/annotation><\/semantics><\/math>\nist die Gleichgewichtslage; die quadratische Näherung gilt nur in ihrer\nUmgebung. Eine größere Masse oder eine stärkere Falle (größeres\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>ω<\/mi><annotation encoding=\"application/x-tex\">\\omega<\/annotation><\/semantics><\/math>)\nverkleinert die quantenmechanische Ausdehnung.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>σ<\/mi><mi>x<\/mi><\/msub><mo>=<\/mo><msqrt><mfrac><mi>ℏ<\/mi><mrow><mn>2<\/mn><mi>m<\/mi><mi>ω<\/mi><\/mrow><\/mfrac><\/msqrt><mo>,<\/mo><mspace width=\"2.0em\"><\/mspace><msub><mi>E<\/mi><mi>n<\/mi><\/msub><mo>−<\/mo><msub><mi>V<\/mi><mn>0<\/mn><\/msub><mo>=<\/mo><mi>ℏ<\/mi><mi>ω<\/mi><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mi>n<\/mi><mo>+<\/mo><mfrac><mn>1<\/mn><mn>2<\/mn><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\sigma_x=\\sqrt{\\frac{\\hbar}{2m\\omega}},\\qquad E_n-V_0=\\hbar\\omega\\left(n+\\frac12\\right).<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Betrachten wir ein hypothetisches Atom mit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>m<\/mi><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>44<\/mn><mo>⋅<\/mo><msup><mn>10<\/mn><mrow><mi>−<\/mi><mn>25<\/mn><\/mrow><\/msup><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">g<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">m=1{,}44\\cdot10^{-25}\\,\\mathrm{kg}<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ω<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>π<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">z<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\omega/(2\\pi)=1{,}0\\,\\mathrm{kHz}<\/annotation><\/semantics><\/math>.\nDann folgt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>σ<\/mi><mi>x<\/mi><\/msub><mo>=<\/mo><msqrt><mrow><mi>ℏ<\/mi><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mi>m<\/mi><mo>⋅<\/mo><mn>2<\/mn><mi>π<\/mi><mo>⋅<\/mo><mn>1000<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msqrt><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>241<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">μ<\/mi><mi mathvariant=\"normal\">m<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\sigma_x=\\sqrt{\\hbar/(2m\\cdot2\\pi\\cdot1000)}\\approx0{,}241\\,\\mathrm{\\mu m}<\/annotation><\/semantics><\/math>.\nDie Energieabstände betragen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>E<\/mi><mo>=<\/mo><mi>h<\/mi><mo>⋅<\/mo><mn>1<\/mn><mo>,<\/mo><mn>0<\/mn><mspace width=\"0.167em\"><\/mspace><mrow><mi mathvariant=\"normal\">k<\/mi><mi mathvariant=\"normal\">H<\/mi><mi mathvariant=\"normal\">z<\/mi><\/mrow><\/mrow><annotation encoding=\"application/x-tex\">\\Delta E=h\\cdot1{,}0\\,\\mathrm{kHz}<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt eine Potentialparabel sowie die\nGrundzustands-Wahrscheinlichkeitsdichte als qualitativen\nQuerschnitt.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_124_DE.svg\"\nalt=\"Harmonisches Fallenpotential mit quantisierten Energieniveaus und einer gaußförmigen Grundzustandswahrscheinlichkeit.\" />\n<figcaption aria-hidden=\"true\">Harmonisches Fallenpotential mit\nquantisierten Energieniveaus und einer gaußförmigen\nGrundzustandswahrscheinlichkeit.<\/figcaption>\n<\/figure>\n<p><em>Die Quantisierung der Fallenbewegung lässt auch im Grundzustand\neine endliche Ortsbreite bestehen.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie verändert sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>σ<\/mi><mi>x<\/mi><\/msub><annotation encoding=\"application/x-tex\">\\sigma_x<\/annotation><\/semantics><\/math>,\nwenn die Fallenfrequenz vervierfacht wird?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Wie groß ist der Nullpunktanteil\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>E<\/mi><mn>0<\/mn><\/msub><mo>−<\/mo><msub><mi>V<\/mi><mn>0<\/mn><\/msub><\/mrow><annotation encoding=\"application/x-tex\">E_0-V_0<\/annotation><\/semantics><\/math>\nin Einheiten von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>ℏ<\/mi><mi>ω<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\hbar\\omega<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Warum versagt das harmonische Modell weit oberhalb des\nFallenminimums häufig?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Die Ortsbreite halbiert sich.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><msub><mi>E<\/mi><mn>0<\/mn><\/msub><mo>−<\/mo><msub><mi>V<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>ℏ<\/mi><mi>ω<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>1<\/mn><mi>/<\/mi><mn>2<\/mn><\/mrow><annotation encoding=\"application/x-tex\">(E_0-V_0)/(\\hbar\\omega)=1/2<\/annotation><\/semantics><\/math>.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Höhere Terme der Potentialentwicklung sowie endliche Fallentiefe und\nKopplungen werden relevant.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Nicht jede Falle ist harmonisch; in einem gekoppelten\ndreidimensionalen Potential müssen Normalmoden und Achsen betrachtet\nwerden. Ein klassisches thermisches Atomensemble besitzt nicht dieselbe\nOrtsverteilung wie der quantenmechanische Grundzustand. Die\nBeispielzahlen sind konstruiert und kein Vorschlag für einen realen\nFallenaufbau.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Optische Felder können Atome nicht nur einfangen, sondern in\nnichtlinearen Medien auch neue Frequenzen erzeugen. <a\nhref=\"index.html?course=university_physics&amp;module=M33&amp;lesson=L7&amp;syslang=de&amp;doclang=de&amp;theme=light\">Nächste Lektion<\/a>.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://doi.org/10.1002/qute.202000022\">Quantum Science and Technology – Optical Dipole Trapping in a Parabolic Mirror<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Harmonische Fallen-Näherung mit Grundzustands-Ortsbreite; ausgewählter Modellausdruck; Fachlicher Bezug zur Lektion: M33-L6 – Atomfallen und quantisierte Bewegung im harmonischen Potential · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-422-atomic-and-optical-physics-ii-spring-2013/pages/lecture-notes/\">MIT OpenCourseWare – Atomic and Optical Physics II: Lecture Notes<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kurs- und Skriptindex zu Quantenoptik, Bloch-Gleichungen, Kühlung und Metrologie; ausgewählte Themen; Fachlicher Bezug zur Lektion: M33-L6 – Atomfallen und quantisierte Bewegung im harmonischen Potential · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>","university_physics_de:M33-L7":"<article class=\"lesson-standard\"><h1 id=\"L7\">M33-L7 – Nichtlineare Optik: Frequenzverdopplung und Phasenanpassung<\/h1>\n<p><strong>Kursbereich:<\/strong> M33 – Master: Atom-, Molekül- und optische Physik<\/p>\n<p><strong>Niveau:<\/strong> Master · fachliche Vertiefung<\/p>\n<p><strong>Voraussetzungen:<\/strong> M15: Wellenoptik und Dispersion;\nM32-L4: Spektroskopie; M33-L4.<\/p>\n<p><strong>Lernziel:<\/strong> Die Skalierung der Frequenzverdopplung mit\nPumpintensität, Kristalllänge und Phasenfehlanpassung auswerten.<\/p>\n<h2 id=\"S1\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Leitfrage und Einordnung<\/h2>\n<p>In einem nichtzentrosymmetrischen Medium kann die elektrische\nPolarisation einen quadratischen Anteil in der Feldstärke enthalten. Ein\neinfallendes Feld der Frequenz ω erzeugt dadurch einen\nPolarisationsanteil bei 2ω und kann Licht der zweiten Harmonischen\nanregen. Entscheidend ist nicht allein die Nichtlinearität: Wellen mit\nunterschiedlichem Phasenfortschritt können sich entlang des Kristalls\nteilweise auslöschen.<\/p>\n<h2 id=\"S2\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Physikalisches Modell und Herleitung<\/h2>\n<p>Für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi>P<\/mi><mo>=<\/mo><msub><mi>ϵ<\/mi><mn>0<\/mn><\/msub><mo stretchy=\"false\" form=\"prefix\">[<\/mo><msup><mi>χ<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>1<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><mi>E<\/mi><mo>+<\/mo><msup><mi>χ<\/mi><mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><\/msup><msup><mi>E<\/mi><mn>2<\/mn><\/msup><mo>+<\/mo><mi>⋯<\/mi><mo stretchy=\"false\" form=\"postfix\">]<\/mo><\/mrow><annotation encoding=\"application/x-tex\">P=\\epsilon_0[\\chi^{(1)}E+\\chi^{(2)}E^2+\\cdots]<\/annotation><\/semantics><\/math>\nbesitzt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>E<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">E^2<\/annotation><\/semantics><\/math>\nbei sinusförmiger Anregung neben einem Gleichanteil einen Anteil bei\ndoppelter Frequenz. Bei konstanter Pumpintensität, ebener Welle,\nundepletierter Grundwelle und vernachlässigbarer Absorption gilt\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I<\/mi><mrow><mn>2<\/mn><mi>ω<\/mi><\/mrow><\/msub><mo>∝<\/mo><msubsup><mi>d<\/mi><mrow><mi mathvariant=\"normal\">e<\/mi><mi mathvariant=\"normal\">f<\/mi><mi mathvariant=\"normal\">f<\/mi><\/mrow><mn>2<\/mn><\/msubsup><msubsup><mi>I<\/mi><mi>ω<\/mi><mn>2<\/mn><\/msubsup><msup><mi>L<\/mi><mn>2<\/mn><\/msup><msup><mrow><mi mathvariant=\"normal\">sinc<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi mathvariant=\"normal\">Δ<\/mi><mi>k<\/mi><mi>L<\/mi><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">I_{2\\omega}\\propto d_{\\mathrm{eff}}^2I_\\omega^2L^2\\operatorname{sinc}^2(\\Delta kL/2)<\/annotation><\/semantics><\/math>\nmit\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mrow><mi mathvariant=\"normal\">sinc<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mrow><mi mathvariant=\"normal\">sin<\/mi><mo>&#8289;<\/mo><\/mrow><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>x<\/mi><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mi>/<\/mi><mi>x<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\operatorname{sinc}(x)=\\sin(x)/x<\/annotation><\/semantics><\/math>\nund\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>k<\/mi><mo>=<\/mo><msub><mi>k<\/mi><mrow><mn>2<\/mn><mi>ω<\/mi><\/mrow><\/msub><mo>−<\/mo><mn>2<\/mn><msub><mi>k<\/mi><mi>ω<\/mi><\/msub><\/mrow><annotation encoding=\"application/x-tex\">\\Delta k=k_{2\\omega}-2k_\\omega<\/annotation><\/semantics><\/math>.\nDie Proportionalitätskonstante enthält unter anderem Brechungsindizes\nund Frequenzfaktoren. Nur bei\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>k<\/mi><mo>=<\/mo><mn>0<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\Delta k=0<\/annotation><\/semantics><\/math>\nbleibt die\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>L<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">L^2<\/annotation><\/semantics><\/math>-Skalierung\nohne Phasenverlust erhalten.<\/p>\n<p><math display=\"block\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msub><mi>I<\/mi><mrow><mn>2<\/mn><mi>ω<\/mi><\/mrow><\/msub><mo>∝<\/mo><msubsup><mi>I<\/mi><mi>ω<\/mi><mn>2<\/mn><\/msubsup><msup><mi>L<\/mi><mn>2<\/mn><\/msup><msup><mrow><mi mathvariant=\"normal\">sinc<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mspace width=\"-0.167em\"><\/mspace><mrow><mo stretchy=\"true\" form=\"prefix\">(<\/mo><mfrac><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>k<\/mi><mi>L<\/mi><\/mrow><mn>2<\/mn><\/mfrac><mo stretchy=\"true\" form=\"postfix\">)<\/mo><\/mrow><mi>.<\/mi><\/mrow><annotation encoding=\"application/x-tex\">I_{2\\omega}\\propto I_\\omega^2L^2\\operatorname{sinc}^2\\!\\left(\\frac{\\Delta kL}{2}\\right).<\/annotation><\/semantics><\/math><\/p>\n<h2 id=\"S3\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Rechenbeispiel und Lehrgrafik<\/h2>\n<p>Bei perfekter Phasenanpassung liefert eine Verdoppelung von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mi>L<\/mi><annotation encoding=\"application/x-tex\">L<\/annotation><\/semantics><\/math>\nim Grenzfall einer undepletierten Pumpe den Faktor vier; eine\nVerdoppelung von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>I<\/mi><mi>ω<\/mi><\/msub><annotation encoding=\"application/x-tex\">I_\\omega<\/annotation><\/semantics><\/math>\nebenfalls den Faktor vier. Gilt dagegen\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><mi mathvariant=\"normal\">Δ<\/mi><mi>k<\/mi><mi>L<\/mi><mo>=<\/mo><mi>π<\/mi><\/mrow><annotation encoding=\"application/x-tex\">\\Delta kL=\\pi<\/annotation><\/semantics><\/math>,\nist die normierte Phasenanpassung\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mrow><mi mathvariant=\"normal\">sinc<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mi>π<\/mi><mi>/<\/mi><mn>2<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><mo>=<\/mo><mn>4<\/mn><mi>/<\/mi><msup><mi>π<\/mi><mn>2<\/mn><\/msup><mo>≈<\/mo><mn>0<\/mn><mo>,<\/mo><mn>405<\/mn><\/mrow><annotation encoding=\"application/x-tex\">\\operatorname{sinc}^2(\\pi/2)=4/\\pi^2\\approx0{,}405<\/annotation><\/semantics><\/math>.\nDie Grafik zeigt das Maximum bei null Fehlanpassung und die abfallenden\nNebenkeulen.<\/p>\n<figure>\n<img src=\"../learning-courses-university-physics-de/media/img/U_PHY_259_DE.svg\"\nalt=\"Normierte sinc-Quadrat-Phasenanpassungsfunktion mit Maximum bei null und Nebenkeulen zu beiden Seiten.\" />\n<figcaption aria-hidden=\"true\">Normierte\nsinc-Quadrat-Phasenanpassungsfunktion mit Maximum bei null und\nNebenkeulen zu beiden Seiten.<\/figcaption>\n<\/figure>\n<p><em>Im undepletierten Grenzfall vermindert die Phasenfehlanpassung\ndie zweite Harmonische um einen sinc²-Faktor.<\/em><\/p>\n<h2 id=\"S4\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Selbstkontrolle<\/h2>\n<h3 id=\"aufgaben\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Aufgaben<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Wie ändert sich\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>I<\/mi><mrow><mn>2<\/mn><mi>ω<\/mi><\/mrow><\/msub><annotation encoding=\"application/x-tex\">I_{2\\omega}<\/annotation><\/semantics><\/math>\nbei Halbierung von\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msub><mi>I<\/mi><mi>ω<\/mi><\/msub><annotation encoding=\"application/x-tex\">I_\\omega<\/annotation><\/semantics><\/math>\nunter sonst gleichen Bedingungen?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\">Welcher Wert gilt für\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mrow><msup><mrow><mi mathvariant=\"normal\">sinc<\/mi><mo>&#8289;<\/mo><\/mrow><mn>2<\/mn><\/msup><mo stretchy=\"false\" form=\"prefix\">(<\/mo><mn>0<\/mn><mo stretchy=\"false\" form=\"postfix\">)<\/mo><\/mrow><annotation encoding=\"application/x-tex\">\\operatorname{sinc}^2(0)<\/annotation><\/semantics><\/math>?<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Welche reale Wirkung begrenzt die idealisierte\n<math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><msup><mi>L<\/mi><mn>2<\/mn><\/msup><annotation encoding=\"application/x-tex\">L^2<\/annotation><\/semantics><\/math>-Skalierung\nbei hoher Konversion?<\/div><\/li>\n<\/ol>\n<h3 id=\"loesungen\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Lösungen<\/h3>\n<ol type=\"1\" class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">1.<\/span><div class=\"lc-item-content\">Auf ein Viertel.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">2.<\/span><div class=\"lc-item-content\"><math display=\"inline\" xmlns=\"http://www.w3.org/1998/Math/MathML\"><semantics><mn>1<\/mn><annotation encoding=\"application/x-tex\">1<\/annotation><\/semantics><\/math>\nim stetigen Grenzwert.<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">3.<\/span><div class=\"lc-item-content\">Die Pumpe wird verbraucht; außerdem können Absorption und\nGruppenlaufzeitversatz begrenzen.<\/div><\/li>\n<\/ol>\n<h2 id=\"S5\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Gültigkeitsgrenzen und Qualität<\/h2>\n<p>Die angegebene Skalierung gilt nicht als allgemeines Designgesetz für\nfokussierte, ultrakurze oder stark konvertierende Pulse. Phasenanpassung\nhängt von Richtung, Polarisation, Dispersion, Temperatur und\ngegebenenfalls periodischer Polung ab. Die vorliegende Fachquelle\nunterstützt die Skalierung und den sinc²-Term; keine vollständige\nTensorrechnung oder experimentelle Freigabe ist erfolgt.<\/p>\n<h2 id=\"S6\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Zusammenfassung und Ausblick<\/h2>\n<p>Das Modul verbindet atomare Feinstruktur, kohärente Anregung,\nMolekülschwingungen, Quantenlicht, Kühlung, Fallen und\nFrequenzumwandlung.<\/p>\n<h2 id=\"S7\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Quellen (extern)<\/h2>\n<h3 id=\"nachweise\"><span class=\"section-number\" aria-hidden=\"true\"><\/span>Nachweise<\/h3>\n<ul class=\"lc-content-list\" role=\"list\">\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC11239842/\">Scientific Data – Second-Harmonic Generation Tensors<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Quadratische Intensitätsskalierung, quadratische Längenskalierung und sinc²-Phasenanpassung; Fachlicher Bezug zur Lektion: M33-L7 – Nichtlineare Optik: Frequenzverdopplung und Phasenanpassung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<li role=\"listitem\"><span class=\"lc-item-marker\" aria-hidden=\"true\">•<\/span><div class=\"lc-item-content\"><a href=\"https://ocw.mit.edu/courses/8-422-atomic-and-optical-physics-ii-spring-2013/pages/lecture-notes/\">MIT OpenCourseWare – Atomic and Optical Physics II: Lecture Notes<span class=\"lc-external-arrow\" aria-hidden=\"true\">&#8239;↗<\/span><span class=\"sr-only lc-external-hint\"> (externer Link)<\/span><\/a> · Kurs- und Skriptindex zu Quantenoptik, Bloch-Gleichungen, Kühlung und Metrologie; ausgewählte Themen; Fachlicher Bezug zur Lektion: M33-L7 – Nichtlineare Optik: Frequenzverdopplung und Phasenanpassung · Zuletzt abgerufen: 2026-11-21<\/div><\/li>\n<\/ul>\n<\/article>"};
